import {loadRepositoryModule as load} from './load-player-catalogue.mjs';import assert from 'node:assert/strict';const {classicSegments,checkClassicSquad,classicFormation}=load('lib/sbcClassic.ts');const s=classicSegments('sbc-boo-hoo-20261028')[0],r=checkClassicSquad(s,s.formation,s.squad);assert(r.ready);assert.equal(r.chemistry,27);assert.equal(classicFormation(s).lines.flat().find(x=>x.id==='cam').position,'CM');for(const slot of ['st','gk']){let squad={...s.squad,[slot]:s.squad.cam};delete squad.cam;assert(!checkClassicSquad(s,s.formation,squad).ready)}console.log('Boo Hoo: 9 valid players, correct active slots, CM, 27 chemistry; locked slots rejected.');
